CREATE TABLE orders (
 id UUID PRIMARY KEY, idempotency_key VARCHAR(100) UNIQUE NOT NULL, fingerprint TEXT NOT NULL,
 product VARCHAR(32) NOT NULL, quantity INT NOT NULL CHECK(quantity BETWEEN 1 AND 100),
 total NUMERIC(12,2) NOT NULL CHECK(total>0), currency CHAR(3) NOT NULL DEFAULT 'AED',
 status VARCHAR(20) NOT NULL DEFAULT 'ACCEPTED', scenario VARCHAR(20) NOT NULL DEFAULT 'NORMAL',
 replays INT NOT NULL DEFAULT 0 CHECK(replays BETWEEN 0 AND 2), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE outbox (id UUID PRIMARY KEY, order_id UUID NOT NULL REFERENCES orders(id), event_id UUID NOT NULL,
 available_at TIMESTAMPTZ NOT NULL DEFAULT now(), published_at TIMESTAMPTZ, publish_attempts INT NOT NULL DEFAULT 0, last_error TEXT);
CREATE INDEX outbox_due ON outbox(available_at) WHERE published_at IS NULL;
CREATE TABLE inbox (event_id UUID PRIMARY KEY, order_id UUID NOT NULL REFERENCES orders(id), outcome VARCHAR(20) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE attempts (id BIGSERIAL PRIMARY KEY, event_id UUID NOT NULL, order_id UUID NOT NULL REFERENCES orders(id), outcome VARCHAR(30) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit (id BIGSERIAL PRIMARY KEY, order_id UUID NOT NULL REFERENCES orders(id), actor VARCHAR(100) NOT NULL, action VARCHAR(40) NOT NULL, reason VARCHAR(300) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
